a2a:agent-card.a2a:json:
{
  "name": "${aerolinea.agente.nombre}",
  "description": "Agente de atención al cliente de la aerolínea: busca y reserva vuelos, añade parking de AENA y gestiona el pago. Gestiona las reservas con su servidor MCP (decide un LLM) y delega en el agente de AENA por A2A los vuelos, el parking y los pagos.",
  "version": "${aerolinea.agente.version}",
  "protocolVersion": "1.0",
  "provider": { "organization": "${aerolinea.agente.organizacion}", "url": "https://www.example.com" },
  "supportedInterfaces": [
    { "protocolBinding": "JSONRPC",   "url": "${poc.urlPublica}${poc.rutas.aerolinea.agente}/rpc", "protocolVersion": "1.0", "tenant": "" },
    { "protocolBinding": "HTTP+JSON", "url": "${poc.urlPublica}${poc.rutas.aerolinea.agente}",     "protocolVersion": "1.0", "tenant": "" }
  ],
  "capabilities": { "streaming": false, "pushNotifications": false, "extendedAgentCard": false },
  "securitySchemes": {
    "apiKey": { "apiKeySecurityScheme": { "location": "header", "name": "X-API-Key", "description": "API key de la POC (cabecera X-API-Key)" } }
  },
  "securityRequirements": [ { "schemes": { "apiKey": { "list": [] } } } ],
  "skills": [
    {
      "id": "reservar-viaje",
      "name": "Reservar viaje",
      "description": "Entrada: DataPart JSON {accion, datos}. Acciones: buscar_vuelos {origen, destino, fecha, pasajeros}, reservar_vuelo {vueloId, pasajeros, titular{nombre, apellidos, email}}, buscar_parking {localizador | aeropuerto, fechaEntrada, fechaSalida}, reservar_parking {localizador, opcionId, fechaSalida, fechaEntrada?, matricula?}, pagar_reserva {localizador}, consultar_reserva {localizador}. Salida: artifact 'resultado-aerolinea' con el resultado JSON y un resumen en texto.",
      "tags": ["vuelos", "viajes", "reservas", "aerolinea", "parking", "pagos"],
      "examples": [
        "Busca vuelos de Madrid a Londres el 2026-11-20",
        "Reserva el vuelo DA1234_MADLHR_20261120 para Ana López",
        "Añade parking en Barajas a la reserva Q7K2LM y págala"
      ],
      "inputModes": ["application/json", "text/plain"],
      "outputModes": ["application/json", "text/plain"]
    }
  ],
  "defaultInputModes": ["application/json", "text/plain"],
  "defaultOutputModes": ["application/json", "text/plain"]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json skipNullOn="everywhere"
---
{
    status: {
        state: "TASK_STATE_COMPLETED",
        message: {role: "ROLE_AGENT", messageId: uuid(), parts: [{text: vars.resumen}]}
    },
    artifact: {
        artifactId: uuid(),
        name: "resultado-aerolinea",
        description: "Resultado de la acción " ++ vars.accion,
        parts: [
            {data: vars.resultado, mediaType: "application/json"},
            {text: vars.resumen}
        ]
    },
    metadata: {
        correlationId: vars.correlationId,
        accion: vars.accion,
        origenReservas: vars.origenReservas,
        modeloLlm: if (p('aerolinea.agente.usarLlm') == 'true') p('poc.llm.modelo') else null
    }
}

a2a:update-task-status.a2a:status-content:
#[%dw 2.0
output application/json
---
{
    statusUpdate: {
        taskId: vars.a2aCtx.taskId,
        contextId: vars.a2aCtx.contextId,
        status: {
            state: "TASK_STATE_REJECTED",
            message: {
                role: "ROLE_AGENT",
                messageId: uuid(),
                parts: [{ text: error.description default "No autorizado" }]
            }
        }
    }
}]

#[%dw 2.0
output application/json
---
{
    statusUpdate: {
        taskId: vars.a2aCtx.taskId,
        contextId: vars.a2aCtx.contextId,
        status: {
            state: "TASK_STATE_FAILED",
            message: {
                role: "ROLE_AGENT",
                messageId: uuid(),
                parts: [{ text: "La aerolínea no ha podido completar la operación: " ++ (error.description default "error desconocido") ++ " (correlationId: " ++ (vars.correlationId default "") ++ ")" }]
            }
        }
    }
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
    message: {
        messageId: uuid(),
        role: "ROLE_USER",
        metadata: {
            correlationId: vars.correlationId,
            agenteOrigen: vars.segmento.nombre
        },
        parts: [
            {
                data: {accion: vars.peticionAena.accion, argumentos: vars.peticionAena.argumentos},
                mediaType: "application/json"
            },
            {
                text: "La aerolínea solicita a AENA la acción " ++ (vars.peticionAena.accion as String) ++ "."
            }
        ]
    }
}
